// Inhalte der Englisch-App fuer Kyla. IDs nie aendern (Fortschritt und gespeicherte Saetze haengen daran), neue Eintraege nur anhaengen.
// lv = Stufe (1 Gegenwart/can/there is, 2 Vergangenheit/Zukunft/would like, 3 Vergleich/Perfekt/if/should/Meinung).
// Mike 2026-10-02: Saetze lang machen, immer mit Verknuepfung (because, so, that's why, but, when, although, if, otherwise).
// Chinesisch: Traditionell, Taiwan, Trenner "，", keine Gedankenstriche.

// Verknuepfungswoerter: Hilfe-Knopf "說長一點" (ab Stufe lv).
const VERBINDER = [
  {lv:1, en:"because", zh:"因為"}, {lv:1, en:"so", zh:"所以"}, {lv:1, en:"but", zh:"但是"}, {lv:1, en:"and then", zh:"然後"},
  {lv:2, en:"that's why", zh:"所以／這就是為什麼"}, {lv:2, en:"when", zh:"……的時候"}, {lv:2, en:"after that", zh:"之後"},
  {lv:3, en:"although", zh:"雖然"}, {lv:3, en:"if", zh:"如果"}, {lv:3, en:"otherwise", zh:"不然"},
];

